import React, { FC, ReactNode } from "react";
import { Provider } from "react-redux";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";

// Assuming these imports point to your correctly converted TypeScript files
import { store } from "../store/store";
import { FirebaseProvider } from "./FirebaseProvider";

/**
 * Defines the expected props for the Providers component, which is a standard
 * pattern for wrapping the application.
 */
interface ProvidersProps {
  children: ReactNode;
}

// Initialize React Query Client outside of the component to avoid re-creation
const queryClient: QueryClient = new QueryClient({
  defaultOptions: {
    queries: {
      // Sensible defaults for client-side fetching
      staleTime: 5 * 60 * 1000, // 5 minutes
      refetchOnWindowFocus: false,
    },
  },
});

/**
 * The Providers component wraps the entire application with necessary contexts:
 * React Query (Data Fetching), Redux (Global State), and Firebase (Auth/DB).
 * We use the FC (Function Component) type for robust typing.
 */
export const Providers: FC<ProvidersProps> = ({ children }) => {
  return (
    <QueryClientProvider client={queryClient}>
      <Provider store={store}>
        <FirebaseProvider>{children}</FirebaseProvider>
      </Provider>
    </QueryClientProvider>
  );
};
