import { configureStore } from "@reduxjs/toolkit";
// NOTE: Assuming notificationReducer is imported from the correctly typed file
import notificationReducer from "./notificationSlice";

export const store = configureStore({
  reducer: {
    // Reducers should be type-inferred from their respective slices
    notification: notificationReducer,
  },
  // Adding middleware configuration for non-serializable values (like Firebase/Auth objects)
  // is often necessary for larger apps, but we omit it here as requested for simplicity.
  devTools: process.env.NODE_ENV !== "production",
});

// --- Type Definitions for use in useSelector and useDispatch hooks ---

/**
 * Infer the `RootState` and `AppDispatch` types from the store itself.
 * These types are necessary for creating typed versions of the
 * `useSelector` and `useDispatch` hooks.
 */

// Infer the `RootState` type from the store's reducer map
export type RootState = ReturnType<typeof store.getState>;

// Infer the `AppDispatch` type from the store's dispatch function
export type AppDispatch = typeof store.dispatch;
